1	// Simplii Financial Bank Account CSV Parser
2	// Expected format: Date, Transaction Details, Funds Out, Funds In
3	// Date format: MM/DD/YYYY
4	// Amount: Separate columns for debits (Funds Out) and credits (Funds In)
5	
6	import { BaseCSVParser } from './BaseCSVParser';
7	import type { CSVParseResult, ParsedTransaction } from '$lib/models/Transaction';
8	
9	export class SimpliiFinancialParser extends BaseCSVParser {
10		parse(csvContent: string): CSVParseResult {
11			const transactions: ParsedTransaction[] = [];
12			const errors: string[] = [];
13	
14			try {
15				csvContent = this.removeBOM(csvContent);
16				const rows = this.parseCSV(csvContent);
17	
18				if (rows.length < 2) {
19					errors.push('CSV file is empty or has no data rows');
20					return { transactions, errors };
21				}
22	
23				// Validate header
24				const header = rows[0];
25				if (!this.validateFormat(csvContent)) {
26					errors.push(
27						'Invalid Simplii Financial CSV format. Expected columns: Date, Transaction Details, Funds Out, Funds In'
28					);
29					return { transactions, errors };
30				}
31	
32				// Find column indices
33				const dateIdx = header.findIndex((h) => h.toLowerCase().includes('date'));
34				const detailsIdx = header.findIndex(
35					(h) =>
36						h.toLowerCase().includes('transaction details') || h.toLowerCase().includes('details')
37				);
38				const fundsOutIdx = header.findIndex((h) => h.toLowerCase().includes('funds out'));
39				const fundsInIdx = header.findIndex((h) => h.toLowerCase().includes('funds in'));
40	
41				if (dateIdx === -1 || detailsIdx === -1 || fundsOutIdx === -1 || fundsInIdx === -1) {
42					errors.push('Could not find required columns in CSV header');
43					return { transactions, errors };
44				}
45	
46				// Parse data rows
47				for (let i = 1; i < rows.length; i++) {
48					const row = rows[i];
49					if (row.length < 4) continue; // Skip incomplete rows
50	
51					const dateStr = row[dateIdx]?.trim();
52					const description = row[detailsIdx]?.trim();
53					const fundsOutStr = row[fundsOutIdx]?.trim();
54					const fundsInStr = row[fundsInIdx]?.trim();
55	
56					// Skip empty rows
57					if (!dateStr && !description && !fundsOutStr && !fundsInStr) continue;
58	
59					// Parse date
60					const transaction_date = this.parseDate(dateStr);
61					if (!transaction_date) {
62						errors.push(`Row ${i + 1}: Invalid date format "${dateStr}"`);
63						continue;
64					}
65	
66					// Determine amount (funds out is negative, funds in is positive)
67					let rawAmount: number | null = null;
68					if (fundsOutStr) {
69						const parsedOut = this.parseAmount(fundsOutStr);
70						if (parsedOut !== null) {
71							rawAmount = -Math.abs(parsedOut); // Ensure it's negative (expense)
72						}
73					} else if (fundsInStr) {
74						const parsedIn = this.parseAmount(fundsInStr);
75						if (parsedIn !== null) {
76							rawAmount = Math.abs(parsedIn); // Ensure it's positive (deposit)
77						}
78					}
79	
80					if (rawAmount === null) {
81						errors.push(`Row ${i + 1}: Invalid amount (out: "${fundsOutStr}", in: "${fundsInStr}")`);
82						continue;
83					}
84	
85					// Simplii uses negative for expenses — keep as-is (#{#trn2f})
86					const amount = this.normalizeAmount(rawAmount, false);
87	
88					// Validate description
89					if (!description) {
90						errors.push(`Row ${i + 1}: Missing transaction details/description`);
91						continue;
92					}
93	
94					transactions.push({
95						transaction_date,
96						vendor_name: description,
97						amount
98					});
99				}
100			} catch (e: any) {
101				errors.push(`Failed to parse CSV: ${e.message || 'Unknown error'}`);
102			}
103	
104			return { transactions, errors };
105		}
106	
107		validateFormat(csvContent: string): boolean {
108			try {
109				csvContent = this.removeBOM(csvContent);
110				const rows = this.parseCSV(csvContent);
111				if (rows.length === 0) return false;
112	
113				const header = rows[0];
114				// Check for Simplii-specific columns
115				const expectedColumns = ['date', 'transaction details', 'funds out', 'funds in'];
116				return this.hasExpectedColumns(header, expectedColumns);
117			} catch {
118				return false;
119			}
120		}
121	}
