285				const csv = loadCSV('SIMPLII.csv');
286				const result = parser.parse(csv);
287	
288				const interestTransactions = result.transactions.filter((t) =>
289					t.vendor_name.includes('INTEREST')
290				);
291				expect(interestTransactions.length).toBeGreaterThan(0);
292				expect(interestTransactions.every((t) => t.amount > 0)).toBe(true); // Deposits stay positive
293			});
