296				const csv = loadCSV('SIMPLII.csv');
297				const result = parser.parse(csv);
298	
299				const sendTransactions = result.transactions.filter((t) =>
300					t.vendor_name.includes('INTERAC E-TRANSFER SEND')
301				);
302				const receiveTransactions = result.transactions.filter((t) =>
303					t.vendor_name.includes('INTERAC E-TRANSFER RECEIVE')
304				);
305	
306				expect(sendTransactions.length).toBeGreaterThan(0);
307				expect(receiveTransactions.length).toBeGreaterThan(0);
308				expect(sendTransactions.every((t) => t.amount < 0)).toBe(true); // Sent → negative (expense)
309				expect(receiveTransactions.every((t) => t.amount > 0)).toBe(true); // Received → positive (deposit)
310			});
