313				const csv = loadCSV('SIMPLII.csv');
314				const result = parser.parse(csv);
315	
316				const transferTransactions = result.transactions.filter((t) =>
317					t.vendor_name.includes('TRANSFER OUT')
318				);
319				expect(transferTransactions.length).toBeGreaterThan(0);
320				expect(transferTransactions.every((t) => t.amount < 0)).toBe(true); // Transfers out stay negative (expense)
321			});
322		});
323	});
